"""Review the approved composition against actual production-ROM captures."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parent

def main():
 report=json.loads((ROOT/'build-validation.json').read_text());assert report['passed']
 approved=json.loads((ROOT.parent/'conteudo-aprovado.json').read_text())['cases']
 cases=[];help_index=0
 for c in approved:
  name=c['id']
  if c['group']=='Como jogar':help_index+=1;name='help-'+str(help_index)
  if c['id']=='pause-sair':name='exit-confirmation'
  for system in ('ntsc','pal'):assert (ROOT/'validation'/system/(name+'.png')).exists(),name
  cases.append(dict(id=c['id'],group=c['group'],label=c['label'],proposal=c['after'],capture=name+'.png'))
 buttons=''.join('<button data-group="'+g+'">'+g+'</button>' for g in ('Pause','Como jogar','Fases','Diálogos'))
 page='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Plaguefall — interfaces implementadas</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101719;color:#f2dfc0;font:16px/1.5 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:24px}.tag{font-size:12px;color:#ffbf57;letter-spacing:.08em}h1{font-size:30px;line-height:1.2;margin:10px 0}p{color:#bdc3b5;margin:8px 0}a{color:#ffbf57}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:18px 0}button,select{font:15px system-ui;background:#202c2f;color:#f2dfc0;border:1px solid #536266;border-radius:5px;padding:8px 12px}button{cursor:pointer}button[aria-pressed=true]{background:#ffbf57;color:#101719}label{font-size:13px;color:#bdc3b5}select{max-width:100%}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:0;min-width:0}figcaption{font-size:14px;margin-bottom:8px}figure:last-child figcaption{color:#ffbf57}img{width:100%;height:auto;display:block;image-rendering:pixelated;border:1px solid #475256}.checks{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.checks span{padding:4px 10px;border:1px solid #415e4c;border-radius:20px;color:#b4d0ac;font-size:12px}footer{border-top:1px solid #475256;margin-top:22px;padding-top:14px;font-size:13px}code{font-size:11px;overflow-wrap:anywhere}@media(max-width:720px){main{padding:18px}.comparison{grid-template-columns:1fr}h1{font-size:25px}}</style>
<main><div class="tag">PLAGUEFALL / PAINEL DA RESISTÊNCIA / IMPLEMENTADO</div><h1>A direção aprovada, agora dentro do jogo.</h1><p>Papel gasto, metal e cobre em preparação, pause, ajuda e diálogos. À direita, capturas reais da ROM; no pause, os valores vêm da partida.</p><div class="controls" role="group" aria-label="Tipo de tela">'''+buttons+'''</div><div class="controls"><label for="case">Exemplo</label><select id="case"></select><label for="system">Sistema</label><select id="system"><option value="ntsc">NTSC · 60 Hz</option><option value="pal">PAL · 50 Hz</option></select><a href="@ROM@" download>Baixar ROM atualizada</a></div>
<div class="comparison"><figure><figcaption>Proposta visual aprovada</figcaption><img id="proposal" src="@PROPOSAL@propostas/pause-5.png" alt="Proposta aprovada do pause"></figure><figure><figcaption>Implementado · captura da ROM</figcaption><img id="actual" src="@BASE@validation/ntsc/pause-5.png" alt="Pause na ROM atualizada"></figure></div>
<div class="checks"><span>20 localidades em NTSC/PAL</span><span>6 páginas de ajuda</span><span>Estado congelado no pause/guia</span><span>Gráficos restaurados na retomada</span><span>23 transições do mapa por sistema</span></div>
<p>Continuar é a opção inicial. O guia retorna ao pause; B/START retomam. Sair exige confirmação com continuar selecionado. Os atalhos de pular fase estão desativados na ROM normal.</p>
<footer><a href="@BASE@build-validation.json">Relatório da implementação</a> · <a href="@BASE@README.md">Detalhes técnicos</a> · <a href="@PROPOSAL@proposta-aprovada.html">Revisão visual aprovada</a><p>Verificado no Genesis Plus GX. A seleção das fases e a morte são aceleradas por RAM; navegação da interface e retomada usam somente controles sob bloqueio de escrita. Sem teste em console físico ou CRT.<br>SHA-256: <code>'''+report['rom_sha256']+'''</code></p></footer></main>
<script>const cases='''+json.dumps(cases,ensure_ascii=False)+''';const selector=document.getElementById('case'),system=document.getElementById('system');function show(){const c=cases[+selector.value];const proposal=document.getElementById('proposal'),actual=document.getElementById('actual');proposal.src='@PROPOSAL@'+c.proposal;proposal.alt='Proposta aprovada: '+c.label;actual.src='@BASE@validation/'+system.value+'/'+c.capture;actual.alt='ROM '+system.value.toUpperCase()+': '+c.label;}function group(name){for(const b of document.querySelectorAll('[data-group]'))b.setAttribute('aria-pressed',String(b.dataset.group===name));selector.replaceChildren();for(let i=0;i<cases.length;i++)if(cases[i].group===name){const o=document.createElement('option');o.value=i;o.textContent=cases[i].label;selector.append(o);}if(name==='Pause')selector.value=cases.findIndex(c=>c.id==='pause-5');show();}for(const b of document.querySelectorAll('[data-group]'))b.addEventListener('click',()=>group(b.dataset.group));selector.addEventListener('change',show);system.addEventListener('change',show);group('Pause');</script></html>'''
 for path,base,proposal,rom in [(ROOT/'revisao.html','','../','../../../out/release/Plaguefall.bin'),(ROOT.parent/'revisao.html','integracao/','','../../out/release/Plaguefall.bin')]:
  path.write_text(page.replace('@BASE@',base).replace('@PROPOSAL@',proposal).replace('@ROM@',rom))
 print('Published 34 approved/actual pairs, NTSC and PAL.')
if __name__=='__main__':main()
